    fn get_currency_info_returns_seeded_full_row() {
        let env = WowLuaEnv::new().expect("env should initialize");
        let (name, field_count): (String, i32) = env
            .eval(
                r#"
                local info = C_CurrencyInfo.GetCurrencyInfo(2245)
